fast_pseudocode:
@triton.autotune(
    configs=[
        triton.Config({'XBLOCK': 1},  num_warps=1, num_stages=1),
        triton.Config({'XBLOCK': 4},  num_warps=1, num_stages=2),  # pipeline
        triton.Config({'XBLOCK': 128}, num_warps=4, num_stages=2), # pipeline
        # ...
    ]
)
def kernel(in_ptr0, in_ptr1, out_ptr0, ...):
    # streaming load — evict_first prevents L1 pollution
    tmp0 = tl.load(in_ptr0 + offset, mask, eviction_policy='evict_first')
    # reused load — evict_last keeps bias in L1
    tmp3 = tl.load(in_ptr1 + offset, mask, eviction_policy='evict_last')

